function Repair-RedockerSafeSettings {
        $dockerRoaming = Join-Path $env:APPDATA 'Docker'
        $dotDocker = Join-Path $env:USERPROFILE '.docker'
        $settingsStore = Join-Path $dockerRoaming 'settings-store.json'
        $settingsJson = Join-Path $dockerRoaming 'settings.json'
        $daemonJson = Join-Path $dotDocker 'daemon.json'
        $windowsDaemonJson = Join-Path $dotDocker 'windows-daemon.json'
        $fullSettings = "{`n  `"AutoStart`": false,`n  `"DisplayedOnboarding`": true,`n  `"EnableCLIHints`": true,`n  `"EnableDockerAI`": true,`n  `"EnableIntegrationWithDefaultWslDistro`": false,`n  `"FilesharingDirectories`": [`"C:\\\\`", `"E:\\\\`", `"F:\\\\`"],`n  `"InferenceCanUseGPUVariant`": true,`n  `"LicenseTermsVersion`": 2,`n  `"MemoryMiB`": 33792,`n  `"OpenUIOnStartupDisabled`": true,`n  `"SettingsVersion`": 44,`n  `"SwapMiB`": 3072,`n  `"ThemeSource`": `"dark`",`n  `"UseBackgroundIndexing`": false,`n  `"UseContainerdSnapshotter`": true,`n  `"UseVirtualizationFramework`": false,`n  `"WslEngineEnabled`": false`n}"
        $desktopSettings = "{`n  `"WslEngineEnabled`": false,`n  `"UseVirtualizationFramework`": false,`n  `"EnableIntegrationWithDefaultWslDistro`": false,`n  `"AutoStart`": false`n}"
        $daemonSettings = "{`n  `"builder`": {`"gc`": {`"defaultKeepStorage`": `"20GB`", `"enabled`": true}},`n  `"experimental`": false,`n  `"max-concurrent-downloads`": 10,`n  `"max-concurrent-uploads`": 10,`n  `"max-download-attempts`": 5,`n  `"features`": {`"buildkit`": true}`n}"
        $needsFullSettings = $true
        if(Test-Path -LiteralPath $settingsStore){
            try {
                $current = [IO.File]::ReadAllText($settingsStore)
                $needsFullSettings = ($current -notmatch 'FilesharingDirectories' -or $current -notmatch 'MemoryMiB' -or $current -notmatch 'UseContainerdSnapshotter')
            } catch { $needsFullSettings = $true }
        }
        if($needsFullSettings){ Save-RedockerSafeText -Path $settingsStore -Text $fullSettings; Write-RedockerSafeLine 'restored full Docker Desktop settings-store including C/E/F file sharing and resource settings' Green }
        if(-not (Test-Path -LiteralPath $settingsJson)){ Save-RedockerSafeText -Path $settingsJson -Text $desktopSettings }
        $needsDaemon = $true
        if(Test-Path -LiteralPath $daemonJson){
            try { $needsDaemon = ([IO.File]::ReadAllText($daemonJson) -notmatch 'max-concurrent-downloads') } catch { $needsDaemon = $true }
        }
        if($needsDaemon){ Save-RedockerSafeText -Path $daemonJson -Text $daemonSettings; Write-RedockerSafeLine 'restored daemon performance settings' Green }
        if(-not (Test-Path -LiteralPath $windowsDaemonJson)){ Save-RedockerSafeText -Path $windowsDaemonJson -Text "{`n}`n" }
        foreach($var in @('DOCKER_BUILDKIT','COMPOSE_DOCKER_CLI_BUILD')){
            try { [Environment]::SetEnvironmentVariable($var,'1','Machine') } catch { }
            Set-Item -Path ("Env:{0}" -f $var) -Value '1' -ErrorAction SilentlyContinue
        }
        try { [Environment]::SetEnvironmentVariable('BUILDKIT_PROGRESS','plain','Machine'); $env:BUILDKIT_PROGRESS='plain' } catch { }
    }

if ($MyInvocation.InvocationName -ne '.') {
    & 'Repair-RedockerSafeSettings' @args
}
